arguments.command:
python3 -c "
from openpyxl import load_workbook
wb = load_workbook('sales_data.xlsx')
ws = wb['Sales Data']
for row in ws.iter_rows(min_row=1, max_row=10, min_col=1, max_col=7):
    for c in row:
        f = c.number_format
        if f != 'General' or c.font.bold or (c.fill and c.fill.fgColor and c.fill.fgColor.rgb not in (None,'00000000')):
            print(c.coordinate, '| val:', repr(c.value), '| fmt:', f, '| bold:', c.font.bold, '| fill:', c.fill.fgColor.rgb if c.fill else None)
"
